window.VD=window.VD||{};window.VD["seat-cupra/mii-1s"]={"mii-1s-activate-comfort-indicators":"<p><strong>Function:</strong> Activates the convenience turn signals.  </p>\n<p><em>(By default, the number of flashes is 3. You can change this value to any number between 1 and 5.) </em>)  <br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click “ <strong>Select</strong>,” then click “ <strong>09 – Cent. Elect.”</strong><br/><br/><strong>4 – </strong>Click on<strong> “Coding – 07” </strong></p>\n<p><strong>5</strong> – Select module “0” and click “Long Coding Helper”:</p>\n<p><em>Byte <strong>12 </strong>: </em><br/><em>Bit<strong> 5</strong>: “<strong>Comfort Turn Signals active</strong>” checkbox</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/6R0-937-088-B_Module09_Byte12-011f47aa.webp\"/></figure>","mii-1s-activate-coming-home-leaving-home":"<p><strong>Purpose: </strong>To activate Coming-Home / Leaving-Home.  </p>\n<p>(To work properly, the vehicle must be equipped with a light sensor. Headlight switch must be in “Auto” position.   <br/>Without the light sensor, it will be necessary to make a headlight call to activate the coming-home).  </p>\n<p><strong>Procedure: </strong><br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Coding 07</strong>”.</p>\n<p><strong>5</strong> – Select the “0” module and click on “Long Coding Helper”:</p>\n<p>Byte <strong>10 </strong>: <br/>Bit <strong>1</strong>: Check “Leaving-Home (LH) active”<br/>Bit <strong>2</strong>: Check “Coming-Home (CH) active”.</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/vw-polo-6r-cominghome-b8af74dc.webp\"/></figure>","mii-1s-activate-daytime-running-lights-drl":"<p><strong>Purpose:</strong> to activate the daytime running lights (DRL).  </p>\n<p><strong>Procedure: </strong><br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Coding 07</strong>”.</p>\n<p><strong>5</strong> – Select the “0” module and click on “Long Coding Helper”:</p>\n<p><em>Byte <strong>23</strong>: </em><br/><em>Bit <strong>6 : </strong> Check Function “Daytime Running Light (DRL)” active</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/6R0-937-088-B_Module09_Byte23-e94f1178.webp\"/></figure>\n<p><strong>Line 2:</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Coding 07</strong>”.</p>\n<p><strong>5</strong> – Select the “0” module and click on “Long Coding Helper”:</p>\n<p><em>Byte <strong>12 </strong>: </em><br/><em>Bit <strong>1</strong>: Tick “Daytime Running Light (DRL) adjustable (Manually AND/OR instrument Cluster)”.</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/6R0-937-088-B_Module09_Byte12-2c0d5984.webp\"/></figure>","mii-1s-activate-driving-school-mode-rcd-215":"<p><strong>Purpose:</strong> Allows you to add a Driving School mode view to the RCD 215 that displays turn signals, speed, etc. (also ideal for accompanied driving) <br/><br/><br/><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket. <br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Channel 2</strong>”.<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu at the bottom<br/>of the page.<br/>On this menu, select<strong>“1</strong>” and confirm.</p>\n<p><em>To activate, press the key combination “Menu -&gt; On”.  </em></p>","mii-1s-automatic-door-locks":"<p><strong>Purpose: </strong>to set automatic door locking from 15km/h.  </p>\n<p><strong>Procedure: </strong><br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Coding 07</strong>”.</p>\n<p><strong>5</strong> – Select the “0” module and click on “Long Coding Helper”:</p>\n<p><em>Byte <strong>0</strong>: </em><br/><em>Bit <strong>4</strong>: Check “Auto-Lock (Automatic Locking above 15 km/h)”.</em><em><br/></em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/6R0-937-088-B_Module09_Byte0-87553eca.webp\"/></figure>","mii-1s-automatic-door-unlocking":"<p><strong>Purpose: </strong>to configure automatic door unlocking when the ignition key is removed.  </p>\n<p><strong>Procedure: </strong><br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Coding 07</strong>”.</p>\n<p><strong>5</strong> – Select the “0” module and click on “Long Coding Helper”:</p>\n<p><em>Byte <strong>0</strong>: </em><br/><em>Bit <strong>3</strong>: Check “Auto-Unlock (Unlocking when Removing the Ignition Key)”.</em><em><br/></em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/6R0-937-088-B_Module09_Byte0-87553eca.webp\"/></figure>","mii-1s-change-number-of-flashes-comfort-flashers":"<p><strong>Purpose:</strong> Allows you to change the number of flashes after activating the comfort turn signals.  <br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click “ <strong>Select</strong>,” then click “ <strong>09 – Cent. Elect.”</strong><br/><br/><strong>4 – </strong>Click on<strong> “Adaptation – 10” </strong></p>\n<p>5 – Select<strong> Channel 43</strong> (Lights: Comfort Turn Signals (Cycles) from the drop-down list)</p>\n<p><em>Select a value between 1 and 5</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/6R0-937-088-B_Module09_Adaptation_channel43-3a96f44b.webp\"/></figure>","mii-1s-corner-lights":"<p><strong>Purpose:</strong> Allows you to turn on the cornering lights along with the fog lights.  <br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click “ <strong>Select</strong>,” then click “ <strong>09 – Cent. Elect.”</strong><br/><br/><strong>4 – </strong>Click on<strong> “Coding – 07” </strong></p>\n<p><strong>5</strong> – Select module “0” and click “Long Coding Helper”:</p>\n<p><em><strong>Byte 12: </strong></em><br/><em>Bit <strong>6</strong>: Check <strong>“Turn/Cornering Lights</strong> installed/active”</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/6R0-937-088-B_Module09_Byte12-011f47aa.webp\"/></figure>","mii-1s-corner-lights-with-turn-signal":"<p><strong>Purpose:</strong> Enables the cornering lights to turn on along with the fog lights when the turn signal is activated.  <br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click “ <strong>Select</strong>,” then click “ <strong>09 – Cent. Elect.”</strong><br/><br/><strong>4 – </strong>Click on<strong> “Coding – 07” </strong></p>\n<p><strong>5</strong> – Select module “0” and click “Long Coding Helper”:</p>\n<p><em>Byte <strong>21: </strong></em><br/><em>Bit <strong>2: </strong> Check <strong>“Cornering/Turn Lights via Turn Signal active</strong> ”</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/6R0-937-088-B_Module09_Byte21-023ebd48.webp\"/></figure>","mii-1s-delete-belt-alarm":"<p><strong>Purpose:</strong> To suppress the audible alarm and the warning light on the speedometer when driving without a seatbelt.  </p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on “<strong>Select”</strong>, then click on “<strong>17 – Instruments</strong>”.</p>\n<p><strong>4</strong> – Click on “<strong>Coding – 07</strong>” then click on “<strong>Long Coding Helper</strong>” .</p>\n<p><strong>5</strong> – Select byte <strong>1</strong>:<br/>Then uncheck Bit <strong>1: </strong>“<strong>Seatbelt warning active/installed</strong>”.  </p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/6J0-920-802-J_Module17_Byte1-5e3ec890.webp\"/></figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/voyant_ceinture_de_securite-296648a9.webp\"/></figure>","mii-1s-flash-mode-lights-during-emergency-braking":"<p><strong>Purpose</strong>: activates the brake/turn signal lights in flash mode during emergency braking. (On Mii phase 1 only turn signals possible)   </p>\n<p><strong>Procedure: </strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket. <br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Coding 07</strong>”.</p>\n<p><strong>5</strong> – Select the “0” module and click on “Long Coding Helper”:</p>\n<p><em>Byte <strong>12</strong>: </em><br/><em>Bit <strong>3</strong>: Check “Emergency Flashing<em>(Turn Signals) active </em>” (to activate turn signals)</em><br/><em>Bit <strong>4</strong>: Tick “Emergency Brake Flashing (Brake Light) active” (to activate brake lights)</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/6R0-937-088-B_Module09_Byte12-2c0d5984.webp\"/></figure>","mii-1s-rear-daytime-running-lights-drl":"<p><strong>Purpose</strong>: Enables the use of the taillights as daytime running lights (Scandinavian DRL).</p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition, then run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/> 3 – Click on ” <strong>Select”</strong>, then click on ” <strong>Select</strong> ” and run the VCDS program.<strong><strong>09 – Cent. Elect.</strong></strong>” .</p>\n<p><strong>4</strong> – Click on “ <strong>Coding – 07.”</strong></p>\n<p><strong>5</strong> – Select Byte<strong> 12 </strong>:</p>\n<p>Bit <strong>0</strong>: Check <em>“<strong>Daytime running lights via Tails Lights active</strong>”.</em></p>","mii-1s-selective-door-unlocking":"<p><strong>Purpose: Allows </strong>you to configure selective door unlocking. <br/></p>\n<p>When unlocking the vehicle, only the driver’s door is unlocked. To unlock all doors, press the remote control’s unlock button twice.   </p>\n<p><strong>Procedure: </strong><br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Coding 07</strong>”.</p>\n<p><strong>5</strong> – Select the “0” module and click on “Long Coding Helper”:</p>\n<p><em>Byte <strong>0</strong>: </em><br/><em>Bit <strong>0</strong>: Check “Selective Central Locking (Single Door Locking) active”</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/6R0-937-088-B_Module09_Byte0-87553eca.webp\"/></figure>","mii-1s-tear-wiping":"<p><strong>Purpose:</strong> to activate the windshield wipers once more after using the windshield washer, in order to remove any remaining water from the windshield.  </p>\n<p><strong>Procedure:</strong> <br/>1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/>2 – Switch on the ignition, then run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/>3 – Click on ” <strong>Select</strong> “, then click on ” <strong>09 – Cent. Elect.</strong>” . Switch on the ignition and run the VCDS program. 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>4</strong> – Click on <strong>“Coding – 07”</strong> then <strong>“Long Coding Helper”.</strong></p>\n<p><strong>5</strong> – Select byte <strong>14</strong>, <br/>Bit <strong>4</strong>, Check <strong>“Tear Wiping Active”</strong>.</p>"};
